package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"strings"

	"github.com/gin-contrib/sessions"
	"github.com/gin-contrib/sessions/cookie"
	"github.com/gin-gonic/gin"
)

var (
	clientID     = os.Getenv("OAUTH_CLIENT_ID")
	clientSecret = os.Getenv("OAUTH_CLIENT_SECRET")
	oauthBaseURL = os.Getenv("OAUTH_PROVIDER_URL")
	allowedHosts = []string{"app.example.com", "staging.example.com"}
)

func generateState() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func validateRedirectURI(redirectURI string) bool {
	parsed, err := url.Parse(redirectURI)
	if err != nil {
		return false
	}
	// Validate scheme
	if parsed.Scheme != "https" && parsed.Scheme != "http" {
		return false
	}
	// Check host against allowlist
	host := parsed.Hostname()
	for _, allowed := range allowedHosts {
		if strings.HasSuffix(host, allowed) {
			return true
		}
	}
	return false
}

func main() {
	r := gin.Default()
	store := cookie.NewStore([]byte(os.Getenv("SESSION_SECRET")))
	r.Use(sessions.Sessions("authsession", store))

	r.GET("/auth/login", func(c *gin.Context) {
		redirectURI := c.Query("redirect_uri")
		if redirectURI == "" {
			redirectURI = "https://app.example.com/dashboard"
		}

		if !validateRedirectURI(redirectURI) {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid redirect_uri"})
			return
		}

		session := sessions.Default(c)
		state := generateState()
		session.Set("oauth_state", state)
		session.Set("redirect_uri", redirectURI)
		session.Save()

		authURL := fmt.Sprintf("%s/authorize?client_id=%s&state=%s&redirect_uri=%s&response_type=code",
			oauthBaseURL, clientID, state, url.QueryEscape("https://app.example.com/auth/callback"))
		c.Redirect(http.StatusFound, authURL)
	})

	r.GET("/auth/callback", func(c *gin.Context) {
		session := sessions.Default(c)
		savedState := session.Get("oauth_state")
		queryState := c.Query("state")

		if savedState == nil || savedState.(string) != queryState {
			c.JSON(http.StatusForbidden, gin.H{"error": "state mismatch"})
			return
		}

		code := c.Query("code")
		if code == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "missing code"})
			return
		}

		// Exchange code for token (simplified)
		token, err := exchangeCodeForToken(code)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": "token exchange failed"})
			return
		}

		session.Set("access_token", token)
		session.Save()

		// Redirect to the originally requested URI
		redirectURI := session.Get("redirect_uri")
		if redirectURI != nil {
			c.Redirect(http.StatusFound, redirectURI.(string))
			return
		}
		c.Redirect(http.StatusFound, "/dashboard")
	})

	r.GET("/dashboard", func(c *gin.Context) {
		session := sessions.Default(c)
		token := session.Get("access_token")
		if token == nil {
			c.Redirect(http.StatusFound, "/auth/login")
			return
		}
		c.JSON(http.StatusOK, gin.H{"message": "authenticated", "user": "current_user"})
	})

	r.Run(":8080")
}

func exchangeCodeForToken(code string) (string, error) {
	// In production this calls the OAuth provider's token endpoint
	// Simplified for demonstration
	if code == "" {
		return "", fmt.Errorf("empty code")
	}
	return "access_token_" + code, nil
}
